        for (int i = 0; i < notes.length; i++)
            if (notes[i] > 0) out.add(CashDispenser.NOTES[i] + "x" + notes[i]);
        return out.toString();
    }
}

// ATM：门面，持有当前状态、会话里的账户和出钞机 / Facade: the current state, the session's account, the dispenser.
