    static final int LIMIT = 2000; // 单笔上限 / per-withdrawal limit
    static final int MAX_TRIES = 3;
    static final State IDLE = new IdleState(), CARD_INSERTED = new CardInsertedState(), AUTHENTICATED = new AuthenticatedState();

