    // Everyone takes the lower-numbered fork first, so no cycle of waiting can form.
    void dine(int p, function<void(int)> pick, function<void()> eat, function<void(int)> drop) {
        int first = min(p, (p + 1) % n), second = max(p, (p + 1) % n);
        lock_guard<mutex> hold_first(forks[first]);
        pick(first);
