    private final ReentrantLock[] forks;

    DiningTable(int n) {
        this.n = n;
        forks = new ReentrantLock[n];
        for (int i = 0; i < n; i++) forks[i] = new ReentrantLock();
    }

    // Everyone takes the lower-numbered fork first, so no cycle of waiting can form.
    void dine(int p, IntConsumer pick, Runnable eat, IntConsumer drop) throws InterruptedException {
        int first = Math.min(p, (p + 1) % n), second = Math.max(p, (p + 1) % n);
        forks[first].lock();
        try {
            pick.accept(first);
            forks[second].lock();
            try {
                pick.accept(second);
                eat.run();
                drop.accept(second);
            } finally {
                forks[second].unlock();
