// DiningTable 哲学家就餐 / Dining philosophers: n at a round table, fork p between philosopher p and p + 1.
type DiningTable struct {
	n     int
	forks []sync.Mutex
}

func NewDiningTable(n int) *DiningTable { return &DiningTable{n: n, forks: make([]sync.Mutex, n)} }

// Dine takes the lower-numbered fork first, so no cycle of waiting can form.
func (t *DiningTable) Dine(p int, pick func(int), eat func(), drop func(int)) {
	first, second := p, (p+1)%t.n
	if first > second {
		first, second = second, first
	}
	t.forks[first].Lock()
	pick(first)
	t.forks[second].Lock()
	pick(second)
	eat()
	drop(second)
	t.forks[second].Unlock()
	drop(first)
	t.forks[first].Unlock()
}

