import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

// 交替输出 / Take turns: foo and bar each call emit n times, foo first, strictly alternating.
class FooBar {
    private final int n;
    private final Semaphore fooTurn = new Semaphore(1);
    private final Semaphore barTurn = new Semaphore(0);

    FooBar(int n) {
        this.n = n;
    }

    void foo(Runnable emit) throws InterruptedException {
        for (int i = 0; i < n; i++) {
            fooTurn.acquire();
            emit.run();
            barTurn.release();
        }
    }

    void bar(Runnable emit) throws InterruptedException {
        for (int i = 0; i < n; i++) {
            barTurn.acquire();
            emit.run();
            fooTurn.release();
        }
    }
}

