	return -1
}

func (m *HashMap) Remove(key int) bool {
	i := index(key, len(m.table))
	chain := m.table[i]
	for j, e := range chain {
		if e.key == key {
			chain[j] = chain[len(chain)-1]
			m.table[i] = chain[:len(chain)-1]
			m.size--
			return true
		}
	}
	return false
}

func (m *HashMap) Size() int { return m.size }

func (m *HashMap) Buckets() int { return len(m.table) }

