// PrefixFunction 前缀函数 / pi[i]: longest proper prefix of p[0..i] that is also its suffix.
func PrefixFunction(p string) []int {
	pi := make([]int, len(p))
	for i := 1; i < len(p); i++ {
		j := pi[i-1]
		for j > 0 && p[i] != p[j] {
			j = pi[j-1]
		}
		if p[i] == p[j] {
			j++
		}
