func FindAll(t, p string) []int {
	pi, out, j := PrefixFunction(p), []int{}, 0
	for i := 0; i < len(t); i++ {
		for j > 0 && t[i] != p[j] {
			j = pi[j-1]
		}
		if t[i] == p[j] {
			j++
		}
		if j == len(p) {
			out = append(out, i-j+1)
			j = pi[j-1]
		}
	}
