class LinkedList:
    """单链表 / Singly linked list with head and tail pointers."""

    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0

    def push_front(self, x: int) -> None:
        self.head = Node(x, self.head)
        if self.tail is None:
            self.tail = self.head
        self.length += 1

    def push_back(self, x: int) -> None:
        node = Node(x)
        if self.tail is None:
            self.head = node
        else:
            self.tail.next = node
        self.tail = node
        self.length += 1

    def pop_front(self) -> int:
        node = self.head
        self.head = node.next
        if self.head is None:
            self.tail = None
        self.length -= 1
        return node.val

    def insert(self, i: int, x: int) -> None:
        if i == 0:
            return self.push_front(x)
        if i == self.length:
            return self.push_back(x)
        prev = self.head
        for _ in range(i - 1):
            prev = prev.next
        prev.next = Node(x, prev.next)
        self.length += 1

    def remove(self, x: int) -> bool:
        prev, node = None, self.head
        while node is not None and node.val != x:
            prev, node = node, node.next
        if node is None:
            return False
        if prev is None:
            self.head = node.next
        else:
            prev.next = node.next
        if node is self.tail:
            self.tail = prev
        self.length -= 1
        return True

    def reverse(self) -> None:
        prev, node = None, self.head
        self.tail = node
        while node is not None:
            node.next, prev, node = prev, node, node.next
        self.head = prev

    def size(self) -> int:
        return self.length

    def values(self) -> list:
        out, node = [], self.head
        while node is not None:
            out.append(node.val)
            node = node.next
        return out


