class LinkedList {
    Node* head = nullptr;
    Node* tail = nullptr;
    int length = 0;

public:
    void push_front(int x) {
        head = new Node(x, head);
        if (!tail) tail = head;
        length++;
    }

    void push_back(int x) {
        Node* node = new Node(x);
        if (tail) tail->next = node;
        else head = node;
        tail = node;
        length++;
    }

    int pop_front() {
        Node* node = head;
        head = node->next;
        if (!head) tail = nullptr;
        length--;
        int val = node->val;
        delete node;
        return val;
    }

    void insert(int i, int x) {
        if (i == 0) return push_front(x);
        if (i == length) return push_back(x);
        Node* prev = head;
        for (int k = 0; k < i - 1; k++) prev = prev->next;
        prev->next = new Node(x, prev->next);
        length++;
    }

    bool remove(int x) {
        Node* prev = nullptr;
        Node* node = head;
        while (node && node->val != x) prev = node, node = node->next;
        if (!node) return false;
        if (prev) prev->next = node->next;
        else head = node->next;
        if (node == tail) tail = prev;
        length--;
        delete node;
        return true;
    }

    void reverse() {
        Node* prev = nullptr;
        Node* node = head;
        tail = head;
        while (node) {
            Node* next = node->next;
            node->next = prev;
            prev = node;
            node = next;
        }
        head = prev;
