// LRU 缓存 / LRU cache: a hash map to the nodes of a doubly linked list, most recent first.
class LRUCache {
    private final int capacity;
    private final Map<Integer, Node> nodes = new HashMap<>();
    private final Node head = new Node(0, 0), tail = new Node(0, 0); // sentinels

    LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    private void unlink(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void pushFront(Node node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }

    int get(int key) {
        Node node = nodes.get(key);
        if (node == null) return -1;
        unlink(node);
        pushFront(node);
        return node.value;
    }

    int put(int key, int value) {
        Node node = nodes.get(key);
        if (node != null) {
            node.value = value;
            unlink(node);
            pushFront(node);
            return -1;
        }
        node = new Node(key, value);
        nodes.put(key, node);
        pushFront(node);
        if (nodes.size() <= capacity) return -1;
        Node oldest = tail.prev;
        unlink(oldest);
        nodes.remove(oldest.key);
        return oldest.key;
    }

    List<Integer> keys() {
        List<Integer> out = new ArrayList<>();
        for (Node node = head.next; node != tail; node = node.next) out.add(node.key);
        return out;
    }
}

