// expire 到期的锁座自动释放 / Release every active hold whose time is up (expires <= t).
func (s *Show) expire(t int64) {
	for len(s.queue) > 0 && s.queue[0].expires <= t {
		hold := s.queue[0]
		s.queue = s.queue[1:]
		if hold.status == ACTIVE {
			hold.status = EXPIRED
			s.freeSeats(hold)
		}
	}
