// 按序执行 / Run in order: three threads call first, second and third once each, in any order.
class InOrder {
    mutex mu;
    condition_variable cv;
    int done = 0;  // jobs finished so far

    void run(int step, function<void()>& job) {
        unique_lock<mutex> lock(mu);
        cv.wait(lock, [&] { return done == step; });
        lock.unlock();
        job();
        lock.lock();
        done = step + 1;
        cv.notify_all();
    }

public:
    void first(function<void()> job) { run(0, job); }

    void second(function<void()> job) { run(1, job); }

    void third(function<void()> job) { run(2, job); }
};

