// 读写锁 / Read-write lock: many readers at once, or a single writer alone.
// Build it yourself: no std::shared_mutex.
class RWLock {
    mutex mu;
    condition_variable cv;
    int readers = 0;  // readers holding the lock
    bool writing = false;
    int waiting_writers = 0;  // new readers wait for these, so writers do not starve

public:
    void acquire_read() {
        unique_lock<mutex> lock(mu);
        cv.wait(lock, [&] { return !writing && waiting_writers == 0; });
        readers++;
    }

    void release_read() {
        lock_guard<mutex> lock(mu);
        if (--readers == 0) cv.notify_all();
    }

    void acquire_write() {
        unique_lock<mutex> lock(mu);
        waiting_writers++;
        cv.wait(lock, [&] { return !writing && readers == 0; });
        waiting_writers--;
        writing = true;
    }

    void release_write() {
        lock_guard<mutex> lock(mu);
        writing = false;
        cv.notify_all();
    }
};

