import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

// 读写锁 / Read-write lock: many readers at once, or a single writer alone.
// Build it yourself: no ReentrantReadWriteLock or StampedLock.
class RWLock {
    private int readers; // readers holding the lock
    private boolean writing;
    private int waitingWriters; // new readers wait for these, so writers do not starve

    synchronized void acquireRead() throws InterruptedException {
        while (writing || waitingWriters > 0) wait();
        readers++;
    }

    synchronized void releaseRead() {
        if (--readers == 0) notifyAll();
    }

    synchronized void acquireWrite() throws InterruptedException {
        waitingWriters++;
        try {
            while (writing || readers > 0) wait();
        } finally {
            waitingWriters--;
        }
        writing = true;
    }

    synchronized void releaseWrite() {
        writing = false;
        notifyAll();
    }
}

// —— 以下驱动代码请勿修改 / Driver code below: do not modify ——
public class Main {
    static final StringBuilder out = new StringBuilder();
