	"time"
)

// RWLock 读写锁 / Read-write lock: many readers at once, or a single writer alone.
// Build it on sync.Mutex and sync.Cond, not sync.RWMutex.
type RWLock struct {
	mu             sync.Mutex
	cond           *sync.Cond
	readers        int // readers holding the lock
	writing        bool
	waitingWriters int // new readers wait for these, so writers do not starve
}

func NewRWLock() *RWLock {
	l := &RWLock{}
	l.cond = sync.NewCond(&l.mu)
	return l
}

func (l *RWLock) AcquireRead() {
	l.mu.Lock()
	for l.writing || l.waitingWriters > 0 {
		l.cond.Wait()
	}
	l.readers++
	l.mu.Unlock()
}

func (l *RWLock) ReleaseRead() {
	l.mu.Lock()
	if l.readers--; l.readers == 0 {
		l.cond.Broadcast()
	}
	l.mu.Unlock()
}

func (l *RWLock) AcquireWrite() {
	l.mu.Lock()
	l.waitingWriters++
	for l.writing || l.readers > 0 {
		l.cond.Wait()
	}
	l.waitingWriters--
	l.writing = true
	l.mu.Unlock()
}

func (l *RWLock) ReleaseWrite() {
	l.mu.Lock()
	l.writing = false
	l.cond.Broadcast()
	l.mu.Unlock()
}

