        node = self.root
        node.pass_count += 1
        for ch in word:
            c = ord(ch) - 97
            if node.children[c] is None:
                node.children[c] = Node()
            node = node.children[c]
            node.pass_count += 1
        node.end_count += 1

    def erase(self, word: str) -> bool:
