        if (rank[a] == rank[b]) rank[a]++;
        sets--;
        return true;
    }

    boolean same(int a, int b) {
        return find(a) == find(b);
    }

    int size(int x) {
        return sizes[find(x)];
    }

    int count() {
        return sets;
    }
}

